<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code (with manual adjustments).

namespace Tests\User\Action\Command;

use Module\User\Action\Command\AdminLoginCmd;
use Module\User\Action\Dto\AdminLoginRequestDto;
use Module\User\Model\User;
use Module\User\Model\UserRepository;
use Module\User\Support\TokenService;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Symfony\Component\PasswordHasher\Hasher\UserPasswordHasherInterface;
use Tests\IntegrationTestCase;

class AdminLoginCmdTest extends IntegrationTestCase
{
    private AdminLoginCmd $sut;

    private UserRepository $userRepository;

    public function setUp(): void
    {
        parent::setUp();

        $this->userRepository = $this->container->get(UserRepository::class);

        $tokenService = $this->createStub(TokenService::class);
        $tokenService->method('generateToken')->willReturn('new-token');

        $this->sut = new AdminLoginCmd(
            $this->userRepository,
            $this->container->get(UserPasswordHasherInterface::class),
            $tokenService,
        );

        $this->prepareDb();
    }

    #[Test, DataProvider('dataProviderHandle')]
    public function handle(
        string $email,
        string $expectedToken,
        int $expectedUserCount,
    ): void {
        $this->assertEquals(1, $this->userRepository->count());

        $result = $this->sut->handle(new AdminLoginRequestDto($email));

        $this->assertSame($expectedToken, $result->token);
        $this->assertEquals($expectedUserCount, $this->userRepository->count());
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderHandle(): array
    {
        return [
            'existing user returns stored token' => [
                'email' => 'existing@example.com',
                'expectedToken' => 'existing-token',
                'expectedUserCount' => 1,
            ],
            'new user is created and token is generated' => [
                'email' => 'new@example.com',
                'expectedToken' => 'new-token',
                'expectedUserCount' => 2,
            ],
        ];
    }

    private function prepareDb(): void
    {
        $user = User::factory('existing@example.com', 'Existing User', 'hashed', ['ROLE_USER'], 'existing-token');
        $this->userRepository->save($user, true);
    }
}
